class Solution {
    string s;int memo[11][1024][2];
    int dfs(int pos,int mask,int started,bool tight){
        if(pos==(int)s.size())return started;
        int &cached=memo[pos][mask][started];
        if(!tight && cached!=-1)return cached;
        int limit=tight?s[pos]-'0':9,ans=0;
        for(int d=0;d<=limit;++d){
            bool ns=started||d!=0;
            if(ns&&(mask&(1<<d)))continue;
            ans+=dfs(pos+1,mask|(ns?(1<<d):0),ns,tight&&d==limit);
        }
        if(!tight)cached=ans;
        return ans;
    }
public:
    int countSpecialNumbers(int n){s=to_string(n);memset(memo,-1,sizeof(memo));return dfs(0,0,0,true);}
};
